-- SwiftPay V2 A3 real-runtime acceptance fixture.
-- TEST ONLY. The plaintext API Secret Key is generated by the acceptance harness;
-- only the supplied scrypt verifier is persisted. This fixture is separate from
-- K5 and from the A2 runtime fixture.

begin;

insert into app.merchants (id, name, lifecycle_status) values
  ('73000000-0000-0000-0000-000000000001'::uuid, 'A3 Runtime Owner Merchant', 'active'),
  ('73000000-0000-0000-0000-000000000002'::uuid, 'A3 Runtime Foreign Merchant', 'active')
on conflict (id) do update set
  name = excluded.name,
  lifecycle_status = 'active',
  suspended_at = null,
  closed_at = null,
  updated_at = now();

