-- Reuse the same deterministic emulator identity that A2 owns. Reasserting it
-- here makes this fixture independently runnable after migrations on a clean DB.
insert into app.providers (id, code, name, status) values (
  '65000000-0000-0000-0000-000000000001'::uuid,
  'swiftpay_emulator',
  'SwiftPay Deterministic Emulator',
  'active'
)
on conflict (id) do update set
  code = excluded.code,
  name = excluded.name,
  status = 'active';

